function apiOrigin() {
  return (process.env.ALPHALAB_API_ORIGIN || 'http://127.0.0.1:8000').replace(/\/+$/, '')
}

async function get(path) {
  const response = await fetch(apiOrigin() + path, { headers: { Accept: 'application/json' } })
  if (!response.ok) throw new Error('AlphaLab API ' + response.status + ': ' + await response.text())
  return response.json()
}

async function run(input) {
  const profile = input.profile === 'runtime' ? 'runtime' : 'demo'
  const accountId = encodeURIComponent(String(input.account_id || 'paper'))
  const limit = Math.max(1, Math.min(200, Number(input.limit || 100)))
  const [account, orders, fills] = await Promise.all([
    get('/api/paper/account?account_id=' + accountId + '&profile=' + profile),
    get('/api/paper/orders?limit=' + limit),
    get('/api/paper/fills?account_id=' + accountId + '&limit=' + limit),
  ])
  return { account, orders, fills }
}
